package com.arena.core.facility;
import com.arena.core.training.*;
import com.arena.core.repository.*;
import com.arena.core.entity.*;
import com.arena.core.service.*;
import com.arena.core.exception.*;
import com.fasterxml.jackson.databind.*;
import java.util.*;import java.math.BigDecimal;import java.time.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;
import org.springframework.boot.test.autoconfigure.jdbc.AutoConfigureTestDatabase;
import org.springframework.boot.test.mock.mockito.*;
import org.springframework.context.annotation.Import;
import org.springframework.test.context.*;
import org.springframework.transaction.annotation.*;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.jdbc.core.JdbcTemplate;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;

/** Explicitly opt-in, local disposable DB only. Never starts a container or contacts Keycloak. */
@DataJpaTest @AutoConfigureTestDatabase(replace=AutoConfigureTestDatabase.Replace.NONE)
@Import({org.springframework.boot.autoconfigure.jackson.JacksonAutoConfiguration.class,com.arena.core.config.DatabaseSchemaConfiguration.class,FacilityService.class,FacilityLedger.class,AuditService.class})
@TestPropertySource(properties={"spring.profiles.active=local","ARENA_DB_SCHEMA=arena_test","spring.jpa.hibernate.ddl-auto=validate","spring.jpa.show-sql=false"})
@EnabledIfEnvironmentVariable(named="ARENA_FACILITY_TEST_DB_URL",matches="jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/arena_test_facilities_[a-z0-9]+")
@Transactional(propagation=Propagation.NOT_SUPPORTED)
class FacilityPostgresTest {
 @DynamicPropertySource static void database(DynamicPropertyRegistry properties){String url=System.getenv("ARENA_FACILITY_TEST_DB_URL");if(url==null||!url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/arena_test_facilities_[a-z0-9]+"))throw new IllegalStateException("Disposable facility database required");properties.add("spring.datasource.url",()->url);properties.add("spring.datasource.username",()->"validation");properties.add("spring.datasource.password",()->"validation");}
 @Autowired FacilityService service;@Autowired CustomerRepository customers;@Autowired AcademySportRepository sports;@Autowired AcademyPlayAreaRepository facilities;@Autowired AuditEventRepository events;@Autowired JdbcTemplate jdbc;@MockBean AcademyAuthorization auth;@MockBean AcademySetupService setup;@SpyBean AuditService audit;
 Long academy,sport;Jwt jwt=Jwt.withTokenValue("isolated").header("alg","none").subject("owner.test").build();ObjectMapper json=new ObjectMapper();
 @BeforeEach void seed(){String name="facility-"+UUID.randomUUID();var c=customers.saveAndFlush(CustomerEntity.builder().customerName(name).parlourName(name).sports("SNOOKER").organizationType("CLUB").onboardingDate(LocalDate.now()).trialStartsAt(LocalDate.now()).trialEndsAt(LocalDate.now().plusDays(14)).subscriptionType("MONTHLY").billingAmount(BigDecimal.ZERO).billingStartDate(LocalDate.now()).nextDueDate(LocalDate.now()).paymentStatus("NOT_DUE").status("ACTIVE").build());academy=c.getId();var s=new AcademySport();s.setAcademyId(academy);s.setCatalogueCode("SNOOKER");s.setName("Snooker");s.setRegistrationKey("SNOOKER");s.setActive(true);s.setSessions(true);sport=sports.saveAndFlush(s).getId();when(auth.manage(any())).thenAnswer(i->{customers.findBillingCustomerForUpdate(academy).orElseThrow();return new AcademyAuthorization.Actor(AppUserEntity.builder().customerId(academy).build(),null,Set.of("OWNER"));});}
 JsonNode body(String text)throws Exception{return json.readTree(text);}
 JsonNode selection()throws Exception{return body("{\"facilities\":[{\"facilityType\":\"ENGLISH\",\"count\":2},{\"facilityType\":\"POOL\",\"count\":1}]}");}
 @Test void creationPersistsIdsNullPricesAndIdempotentOriginalResult()throws Exception{UUID key=UUID.randomUUID();var first=service.create(jwt,academy,sport,key,selection());var second=service.create(jwt,academy,sport,key,selection());assertEquals(first,second);assertEquals(3,first.facilities().stream().map(FacilityContracts.View::facilityId).distinct().count());assertEquals(List.of("E1","E2","P1"),first.facilities().stream().map(FacilityContracts.View::code).toList());assertTrue(first.facilities().stream().allMatch(f->!f.configured()&&f.hourlyRate()==null));assertEquals(3,service.list(jwt,academy,sport).facilities().size());assertEquals(3,events.findByCustomerIdOrderByOccurredAtDesc(academy).size());}
 @Test void payloadReuseRejectedAndNewKeyAllocatesNewCodes()throws Exception{UUID key=UUID.randomUUID();service.create(jwt,academy,sport,key,selection());assertThrows(FacilityFailure.class,()->service.create(jwt,academy,sport,key,body("{\"facilities\":[{\"facilityType\":\"ENGLISH\",\"count\":1}]}")));var added=service.create(jwt,academy,sport,UUID.randomUUID(),selection());assertEquals(List.of("E3","E4","P2"),added.facilities().stream().map(FacilityContracts.View::code).toList());}
 @Test void auditFailureRollsBackFacilitiesCounterAndIdempotency()throws Exception{doThrow(new IllegalStateException("isolated audit failure")).when(audit).record(any(),any(),any(),any(),any(),any(),any(),any());assertThrows(IllegalStateException.class,()->service.create(jwt,academy,sport,UUID.randomUUID(),selection()));assertEquals(0,facilities.findByAcademyIdAndSportIdOrderById(academy,sport).size());assertEquals(0,jdbc.queryForObject("select count(*) from arena_test.facility_code_counter where academy_id=?",Integer.class,academy));assertEquals(0,jdbc.queryForObject("select count(*) from arena_test.facility_operation where academy_id=?",Integer.class,academy));assertEquals(0,events.findByCustomerIdOrderByOccurredAtDesc(academy).size());}
 @Test void staleMemberRejectsEntirePatchAndNullFieldsHaveExplicitMeaning()throws Exception{var rows=service.create(jwt,academy,sport,UUID.randomUUID(),selection()).facilities();Long a=rows.get(0).facilityId(),b=rows.get(1).facilityId();assertThrows(FacilityFailure.class,()->service.patch(jwt,academy,body("{\"facilities\":[{\"facilityId\":"+a+",\"version\":0,\"hourlyRate\":200},{\"facilityId\":"+b+",\"version\":9,\"hourlyRate\":300}]}")));assertNull(facilities.findById(a).orElseThrow().getHourlyRate());var updated=service.patch(jwt,academy,body("{\"facilities\":[{\"facilityId\":"+a+",\"version\":0,\"displayName\":\"VIP\",\"hourlyRate\":200,\"frameRate\":100}]}"));assertEquals(1L,updated.facilities().get(0).version());assertTrue(updated.facilities().get(0).configured());var cleared=service.patch(jwt,academy,body("{\"facilities\":[{\"facilityId\":"+a+",\"version\":1,\"displayName\":null,\"frameRate\":null}]}"));assertEquals(new BigDecimal("200.00"),cleared.facilities().get(0).hourlyRate());assertNull(cleared.facilities().get(0).frameRate());}
 @Test void laterInvalidRateRollsBackEarlierPatchAndAudit()throws Exception{var rows=service.create(jwt,academy,sport,UUID.randomUUID(),selection()).facilities();int before=events.findByCustomerIdOrderByOccurredAtDesc(academy).size();assertThrows(FacilityFailure.class,()->service.patch(jwt,academy,body("{\"facilities\":[{\"facilityId\":"+rows.get(0).facilityId()+",\"version\":0,\"hourlyRate\":200},{\"facilityId\":"+rows.get(1).facilityId()+",\"version\":0,\"hourlyRate\":-1}]}")));assertNull(facilities.findById(rows.get(0).facilityId()).orElseThrow().getHourlyRate());assertEquals(before,events.findByCustomerIdOrderByOccurredAtDesc(academy).size());}
 @Test void concurrentSameKeyCreatesExactlyOneSet()throws Exception{UUID key=UUID.randomUUID();var results=concurrent(key,key);assertEquals(results.get(0),results.get(1));assertEquals(3,service.list(jwt,academy,sport).facilities().size());}
 @Test void concurrentDifferentKeysAllocateDisjointMultiTypeCodes()throws Exception{var results=concurrent(UUID.randomUUID(),UUID.randomUUID());assertEquals(6,results.stream().flatMap(r->r.facilities().stream()).map(FacilityContracts.View::code).distinct().count());assertEquals(6,service.list(jwt,academy,sport).facilities().size());}
 @Test void inactiveLegacyCodesRemainStableAndSeedTheCounter()throws Exception{var legacy=new AcademyPlayArea();legacy.setAcademyId(academy);legacy.setSportId(sport);legacy.setCode("E9");legacy.setName("Original table");legacy.setKind("TABLE");legacy.setActive(false);facilities.saveAndFlush(legacy);var created=service.create(jwt,academy,sport,UUID.randomUUID(),selection());assertEquals("E10",created.facilities().get(0).code());assertEquals("E9",facilities.findById(legacy.getId()).orElseThrow().getCode());assertEquals("Original table",service.list(jwt,academy,sport).facilities().stream().filter(f->f.facilityId().equals(legacy.getId())).findFirst().orElseThrow().displayName());}
 @Test void foreignFacilityAndAuditLookupsAreDenied()throws Exception{var rows=service.create(jwt,academy,sport,UUID.randomUUID(),selection()).facilities();assertThrows(ArenaOpsException.class,()->service.list(jwt,academy+1000000,sport));assertThrows(ArenaOpsException.class,()->service.history(jwt,academy+1000000,rows.get(0).facilityId()));assertThrows(FacilityFailure.class,()->service.patch(jwt,academy,body("{\"facilities\":[{\"facilityId\":999999999,\"version\":0,\"hourlyRate\":100}]}")));}
 private List<FacilityContracts.Result> concurrent(UUID first,UUID second)throws Exception{var pool=Executors.newFixedThreadPool(2);var ready=new CountDownLatch(2);var start=new CountDownLatch(1);try{java.util.function.Function<UUID,Callable<FacilityContracts.Result>> task=key->()->{ready.countDown();if(!start.await(10,TimeUnit.SECONDS))throw new IllegalStateException("Test start timeout");return service.create(jwt,academy,sport,key,selection());};var a=pool.submit(task.apply(first));var b=pool.submit(task.apply(second));assertTrue(ready.await(10,TimeUnit.SECONDS));start.countDown();return List.of(a.get(20,TimeUnit.SECONDS),b.get(20,TimeUnit.SECONDS));}finally{start.countDown();pool.shutdownNow();}}
}
